// BAD: SQL Injection due to improper API usage (string concatenation with user input)
import java.sql.*;
import javax.servlet.http.*;

public class UserLookupServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) {
        String user = request.getParameter("user"); // attacker-controlled input
        // vulnerable: constructing SQL directly with untrusted input
        String sql = "SELECT id, username, email FROM users WHERE username = '" + user + "'";
        try (Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost/app", "app", "secret");
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) { // executes attacker-controlled SQL
            while (rs.next()) {
                response.getWriter().println("User: " + rs.getString("username"));
            }
        } catch (Exception e) {
            // Leaks internal details to clients
            e.printStackTrace(response.getWriter());
        }
    }
}

***

/* GOOD: Use PreparedStatement and avoid leaking internals; validate and encode outputs */
import java.sql.*;
import javax.servlet.http.*;
import org.owasp.encoder.Encode;

public class UserLookupServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) {
        String user = request.getParameter("user");

        // Basic input validation (e.g., allow alphanumerics and limited symbols)
        if (user == null || !user.matches("^[A-Za-z0-9._-]{1,32}$")) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            safeWrite(response, "Invalid username.");
            return;
        }

        String sql = "SELECT id, username, email FROM users WHERE username = ?";
        try (Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost/app", "app", "secret");
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setString(1, user); // parameterized query prevents injection
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    // HTML-encode output to prevent XSS
                    String uname = Encode.forHtml(rs.getString("username"));
                    safeWrite(response, "User: " + uname);
                }
            }
        } catch (SQLException sqle) {
            // Log internally; return generic error to client
            log("Database error during user lookup", sqle);
            response.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
            safeWrite(response, "An error occurred. Please try again later.");
        }
    }

    private void safeWrite(HttpServletResponse response, String msg) {
        try {
            response.setContentType("text/plain; charset=UTF-8");
            response.getWriter().println(msg);
        } catch (Exception ignored) {}
    }
}

