// Poor code: Using string concatenation to build SQL with untrusted input (vulnerable)
import java.io.IOException;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class LoginServletInsecure extends HttpServlet {
    private Connection conn;

    @Override
    public void init() {
        try {
            conn = DriverManager.getConnection("jdbc:mysql://localhost/app", "user", "pass");
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String username = req.getParameter("username"); // untrusted input
        String password = req.getParameter("password"); // untrusted input

        // BAD: vulnerable to SQL injection due to string concatenation (vulnerable)
        String sql = "SELECT id FROM users WHERE username = '" + username + "' AND password = '" + password + "'";

        try (Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) { // attacker can inject ' OR '1'='1
            if (rs.next()) {
                resp.getWriter().write("Welcome!");
            } else {
                resp.getWriter().write("Invalid credentials");
            }
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    @Override
    public void destroy() {
        try { if (conn != null) conn.close(); } catch (SQLException ignored) {}
    }
}
***
/*
 Sound code: Use PreparedStatement with parameters, hash passwords, and apply minimal leakage
 Also demonstrates safe resource handling and basic validation
*/
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class LoginServletSecure extends HttpServlet {
    private DataSource dataSource; // Prefer a pooled DataSource

    @Override
    public void init() {
        // Obtain a DataSource from JNDI in real apps; shown minimally here
        try {
            // Example using DriverManager for brevity; prefer connection pooling in production
            DriverManager.registerDriver(new com.mysql.cj.jdbc.Driver());
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }

    private String sha256(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256"); // Example only; use a password hashing function like bcrypt/Argon2 in production
            byte[] hash = md.digest(input.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(hash.length * 2);
            for (byte b : hash) sb.append(String.format("%02x", b));
            return sb.toString();
        } catch (Exception e) {
            throw new RuntimeException("Hashing failure", e);
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String username = req.getParameter("username");
        String password = req.getParameter("password");

        // Basic input normalization/validation
        if (username == null || password == null || username.length() > 128 || password.length() > 256) {
            resp.sendError(400, "Bad request");
            return;
        }

        String sql = "SELECT id FROM users WHERE username = ? AND password_hash = ?";

        // Use try-with-resources to ensure closure; use PreparedStatement to avoid injection
        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/app", "user", "pass");
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setString(1, username);
            ps.setString(2, sha256(password)); // In production, store salted bcrypt/Argon2 and verify with library

            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    // Good: avoid reflecting sensitive info; set secure headers/cookies as needed
                    resp.getWriter().write("Welcome!");
                } else {
                    // Do not reveal which field failed
                    resp.getWriter().write("Invalid credentials");
                }
            }
        } catch (SQLException e) {
            // Avoid leaking SQL details
            resp.sendError(500, "Server error");
        }
    }
}

